<script setup lang="ts">
import ProductMetrics from '../components/ProductMetrics.vue'
import {ref,onMounted} from 'vue';import {get} from '../api/client'
const props=defineProps<{view:string}>(),data=ref<any>(null),users=ref<any>(null),product=ref<any>(null),metrics=ref<any>(null),error=ref('')
const titles:Record<string,string>={dashboard:'数据看板',content:'内容统计',behavior:'行为统计',profile:'用户概况'}
onMounted(async()=>{try{[data.value,users.value,product.value,metrics.value]=await Promise.all([get('/api/v1/admin/analytics'),get('/api/v1/admin/analytics/users'),get('/api/v1/admin/analytics/product'),get('/api/v1/admin/analytics/product-metrics')])}catch(e){error.value=(e as Error).message}})
</script>
<template><section><h1>{{ titles[props.view] }}</h1><p class="muted">基于实际采集数据，按 Asia/Shanghai 自然日统计。签发下载链接不会计入成功下载。</p><p class="error" role="alert">{{ error }}</p><template v-if="data&&users&&product&&metrics"><div v-if="view==='dashboard'" class="panel"><h2>内容与访问</h2><p>已发布资讯 {{ data.publicationCount }}</p><p>今日访问人数 {{ users.uniqueUsersToday }} · 30 日访问人数 {{ users.uniqueUsers30Days }}</p></div><div v-if="view==='content'" class="panel scroll"><h2>成功下载</h2><table><thead><tr><th>活动</th><th>文件</th><th>下载次数</th></tr></thead><tbody><tr v-for="r in product.downloads" :key="r.activityId+'-'+r.fileId"><td>{{ r.activityTitle }}</td><td>{{ r.fileName }}</td><td>{{ r.downloads }}</td></tr></tbody></table><p v-if="!product.downloads.length">暂无成功下载记录</p><h2>资讯</h2><table><thead><tr><th>内容</th><th>浏览</th><th>浏览人数</th><th>收藏</th></tr></thead><tbody><tr v-for="r in data.content" :key="r.id"><td>{{ r.title }}</td><td>{{ r.viewCount }}</td><td>{{ r.viewerCount }}</td><td>{{ r.favoriteCount }}</td></tr></tbody></table></div><div v-if="view==='behavior'" class="panel scroll"><h2>搜索缺口</h2><table><thead><tr><th>搜索词</th><th>近 30 天次数</th><th>用户数</th></tr></thead><tbody><tr v-for="r in product.searchGaps" :key="r.query"><td>{{ r.query }}</td><td>{{ r.requests }}</td><td>{{ r.users }}</td></tr></tbody></table><p v-if="!product.searchGaps.length">暂无搜索缺口记录</p><h2>每日行为</h2><table><thead><tr><th>日期（上海）</th><th>事件</th><th>次数</th></tr></thead><tbody><tr v-for="(r,i) in data.daily.filter((r:any)=>!['PAGE_STAY','SEARCH_CLICK'].includes(r.metricKey))" :key="i"><td>{{ r.metricDate }}</td><td>{{ r.metricKey }}</td><td>{{ r.value }}</td></tr></tbody></table></div><div v-if="view==='profile'" class="panel"><h2>账号概况</h2><p>有效账号 {{ users.activeAccounts }} · 注销账号 {{ users.closedAccounts }}</p><p class="muted">仅使用账号状态与访问总量。不推测性别、收入、兴趣或其他未经采集的个人画像。</p></div><ProductMetrics :view="view" :product="product" :metrics="metrics"/></template></section></template>
